import React, { useMemo, useState, useEffect } from 'react';
import { Button, Container, Row } from 'react-bootstrap';
import Sidebar from './sidebar.jsx';
import Content from './content.jsx';
import {
  DEFAULT_TOPIC_LABEL_MAP,
  TOPIC_LABEL_STORAGE_KEY,
  readTopicLabelOverrides,
} from './topic-labels.js';

const COMPANY_CACHE_KEY = 'company-list-v1';
const TOPIC_INDEX_CACHE_KEY = 'topic-index-v2';
const SHARED_TOPIC_LABELS_URL = `${process.env.PUBLIC_URL}/data/topic-label-overrides.json`;
const DEFAULT_TOPIC_LIST = ['0', '1', '2', '3', '5', '6', '7', '8', '9', '11', '15', '17', '13', '14', '16', '19', '23', '24', '31', '12', '10'];
const SIDEBAR_WIDTH = 270;
const PATENT_PANEL_WIDTH = 256;

const App = () => {
  const [companyList, setCompanyList] = useState([]);
  const [topicList, setTopicList] = useState(DEFAULT_TOPIC_LIST);
  const [topicRankMap, setTopicRankMap] = useState({});
  const [localTopicNameOverrides, setLocalTopicNameOverrides] = useState(() => readTopicLabelOverrides());
  const [sharedTopicNameOverrides, setSharedTopicNameOverrides] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [isSidebarHidden, setIsSidebarHidden] = useState(false);

  // records.jsonからデータを読み込む
  useEffect(() => {
    const fetchCompanyList = async () => {
      try {
        setIsLoading(true);

        const cachedCompanyList = sessionStorage.getItem(COMPANY_CACHE_KEY);
        if (cachedCompanyList) {
          setCompanyList(JSON.parse(cachedCompanyList));
          setIsLoading(false);
          return;
        }

        const response = await fetch(`${process.env.PUBLIC_URL}/data/records.json`, { cache: 'force-cache' });
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }
        const data = await response.json();

        // 会社名を一度だけ走査して重複を削除
        const namesSet = new Set();
        for (const item of data) {
          if (item?.comp) {
            namesSet.add(item.comp);
          }
        }
        const names = [...namesSet];

        sessionStorage.setItem(COMPANY_CACHE_KEY, JSON.stringify(names));
        setCompanyList(names);
        setIsLoading(false);
      } catch (error) {
        console.error('データの読み込みに失敗しました:', error);
        setIsLoading(false);
      }
    };

    fetchCompanyList();
  }, []);
  
  const [visualType, setVisualType] = useState('one-topic');
  const [isApplied, setIsApplied] = useState(0);
  const [selectedCompanies, setSelectedCompanies] = useState(['株式会社熊谷組']);
  const [selectedTopics, setSelectedTopics] = useState(['0']);

  const handleVisualTypeChange = (value) => {
    setVisualType(value);
  };

  const handleApply = () => {
    setIsApplied(1);
  };

  const toggleSelection = (item, setSelected, buttomtype) => {
    if (buttomtype === 'checkbox') {
      setSelected((prevSelected) =>
        prevSelected.includes(item)
          ? prevSelected.filter((i) => i !== item)
          : [...prevSelected, item]
      );
    } else {
      setSelected([item]);
    }
  };

  const CompanyCheckboxChange = (company, buttomtype) => {
    toggleSelection(company, setSelectedCompanies, buttomtype);
  };

  const TopicCheckboxChange = (topic, buttomtype) => {
    toggleSelection(topic, setSelectedTopics, buttomtype);
  };

  const handleReplaceTopics = (topics) => {
    setSelectedTopics(topics);
  };

  useEffect(() => {
    const fetchTopicIndex = async () => {
      try {
        const cachedTopicIndex = sessionStorage.getItem(TOPIC_INDEX_CACHE_KEY);
        if (cachedTopicIndex) {
          const parsed = JSON.parse(cachedTopicIndex);
          if (Array.isArray(parsed)) {
            // 旧キャッシュ形式との互換
            setTopicList(parsed);
            const fallbackRank = {};
            parsed.forEach((topicId, idx) => {
              fallbackRank[String(topicId)] = idx + 1;
            });
            setTopicRankMap(fallbackRank);
          } else {
            setTopicList(parsed.topicList || DEFAULT_TOPIC_LIST);
            setTopicRankMap(parsed.topicRankMap || {});
          }
          return;
        }

        const response = await fetch(`${process.env.PUBLIC_URL}/data/visualize_data/patents/index.json`, { cache: 'force-cache' });
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();
        const rankedTopics = [...(data.topics || [])]
          .sort((a, b) => Number(b.count || 0) - Number(a.count || 0));
        const topics = rankedTopics.map((item) => String(item.id));
        const rankMap = {};
        rankedTopics.forEach((item, idx) => {
          rankMap[String(item.id)] = idx + 1;
        });

        if (topics.length > 0) {
          setTopicList(topics);
          setTopicRankMap(rankMap);
          sessionStorage.setItem(
            TOPIC_INDEX_CACHE_KEY,
            JSON.stringify({ topicList: topics, topicRankMap: rankMap })
          );
        }
      } catch (error) {
        console.error('トピック一覧の読み込みに失敗しました:', error);
      }
    };

    fetchTopicIndex();
  }, []);

  useEffect(() => {
    setSelectedCompanies(['株式会社熊谷組']);
    setSelectedTopics(['0']);
  }, [visualType]);

  // サイドバー選択変更時に自動で再描画を走らせる
  useEffect(() => {
    if (!isLoading) {
      setIsApplied(1);
    }
  }, [visualType, selectedTopics, selectedCompanies, isLoading]);

  const resetIsApplied = () => {
    setIsApplied(0);
  };

  useEffect(() => {
    const fetchSharedTopicLabels = async () => {
      try {
        const response = await fetch(SHARED_TOPIC_LABELS_URL, { cache: 'no-store' });
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }
        const data = await response.json();
        if (data && typeof data === 'object' && !Array.isArray(data)) {
          setSharedTopicNameOverrides(data);
        }
      } catch (error) {
        console.warn('共有TOPIC表示名の読み込みに失敗:', error);
      }
    };

    fetchSharedTopicLabels();
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(TOPIC_LABEL_STORAGE_KEY, JSON.stringify(localTopicNameOverrides));
    } catch (error) {
      console.error('TOPIC表示名の保存に失敗:', error);
    }
  }, [localTopicNameOverrides]);

  useEffect(() => {
    const handleStorage = () => {
      setLocalTopicNameOverrides(readTopicLabelOverrides());
    };

    window.addEventListener('storage', handleStorage);
    return () => {
      window.removeEventListener('storage', handleStorage);
    };
  }, []);

  const topicLabelMap = useMemo(
    () => ({ ...DEFAULT_TOPIC_LABEL_MAP, ...sharedTopicNameOverrides, ...localTopicNameOverrides }),
    [sharedTopicNameOverrides, localTopicNameOverrides]
  );

  if (isLoading) {
    return <div>データ読み込み中...</div>;
  }

  return (
    <Container id="react-content" fluid className="bg-light">
      <Row className="g-0" style={{ height: '100vh' }}>
        {!isSidebarHidden && (
          <div style={{ width: `${SIDEBAR_WIDTH}px`, borderRight: '1px solid #dee2e6', overflow: 'hidden' }}>
            <Sidebar
              onApply={handleApply}
              visualType={visualType}
              onVisualTypeChange={handleVisualTypeChange}
              topicList={topicList}
              companyList={companyList}
              topicRankMap={topicRankMap}
              topicLabelMap={topicLabelMap}
              topicNameOverrides={localTopicNameOverrides}
              onTopicNameOverridesChange={setLocalTopicNameOverrides}
              selectedCompanies={selectedCompanies}
              selectedTopics={selectedTopics}
              onChangeTopic={TopicCheckboxChange}
              onReplaceTopics={handleReplaceTopics}
              onChangeCompany={CompanyCheckboxChange}
            />
          </div>
        )}

        <div
          style={{
            width: '32px',
            cursor: 'default',
            backgroundColor: '#f8f9fa',
            borderRight: '1px solid #dee2e6',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <Button
            size="sm"
            variant="outline-secondary"
            onClick={() => setIsSidebarHidden((prev) => !prev)}
            style={{ padding: '0.1rem 0.35rem', lineHeight: 1 }}
            title={isSidebarHidden ? 'サイドバーを表示' : 'サイドバーを隠す'}
          >
            {isSidebarHidden ? '>' : '<'}
          </Button>
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <Content
            plot={isApplied}
            visualType={visualType}
            topic={selectedTopics}
            company={selectedCompanies}
            resetApply={resetIsApplied}
            patentPanelWidth={PATENT_PANEL_WIDTH}
            topicLabelMap={topicLabelMap}
          />
        </div>
      </Row>
    </Container>
  );
};

export default App;
