import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Badge, Card, Col, Container, Form, InputGroup, ListGroup, Row, Spinner } from 'react-bootstrap';
import PlotPieA from './occupy.jsx';
import PlotPieB from './occupy-company.jsx';
import PlotPersonaComp from './persona-comp.jsx';
import PlotPersonaTopic from './persona-topic.jsx';
import PlotBarChartA from './trend-topix.jsx';
import PlotBarChartB from './trend-comp.jsx';
import ProposedVisualize from './go-anywhere.jsx';
import { getTopicLabel } from './topic-labels.js';
import * as XLSX from 'xlsx/dist/xlsx.full.min.js';

const MAX_VISIBLE_DOCS = 120;
const MAX_SUBPANEL_RANK = 20;
const DEFAULT_VISIBLE_RANGES = ['1-5'];

const Content = ({
  plot,
  visualType,
  topic,
  company,
  resetApply,
  patentPanelWidth = 220,
  topicLabelMap,
}) => {
  const [clickData, setClickData] = useState();
  const [clickCompanyData, setClickCompanyData] = useState();
  const [topicDocs, setTopicDocs] = useState([]);
  const [docsLoading, setDocsLoading] = useState(false);
  const [docsError, setDocsError] = useState('');
  const [docsSearchTerm, setDocsSearchTerm] = useState('');
  const [isRangeSettingOpen, setIsRangeSettingOpen] = useState(false);
  const [visibleRankRanges, setVisibleRankRanges] = useState(DEFAULT_VISIBLE_RANGES);
  const [isDownloadingDocs, setIsDownloadingDocs] = useState(false);
  const [downloadError, setDownloadError] = useState('');
  const activeTopicId = String(topic?.[0] ?? '');

  const handlePieChartClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickData(data);
  };

  const handlePersonaClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickCompanyData(data);
  };

  useEffect(() => {
    const fetchTopicDocs = async () => {
      if (!activeTopicId) {
        setTopicDocs([]);
        return;
      }

      setDocsLoading(true);
      setDocsError('');
      try {
        const docsUrl = `${process.env.PUBLIC_URL}/data/visualize_data/patents/topic/${activeTopicId}.json`;
        let response = await fetch(docsUrl, { cache: 'force-cache' });
        if (!response.ok) {
          // 直前の404キャッシュが残っている場合に備えて再取得
          response = await fetch(docsUrl, { cache: 'no-store' });
        }
        if (!response.ok) {
          throw new Error(`HTTP ${response.status} (${docsUrl})`);
        }
        const data = await response.json();
        // 文献データが不完全でも描画を壊さないように正規化
        const normalizedDocs = Array.isArray(data)
          ? data
              .filter((doc) => doc && typeof doc === 'object')
              .map((doc) => ({
                number: typeof doc.number === 'string' ? doc.number : '',
                title: typeof doc.title === 'string' ? doc.title : '',
                inventors: Array.isArray(doc.inventors) ? doc.inventors : [],
              }))
          : [];
        setTopicDocs(normalizedDocs);
      } catch (error) {
        setTopicDocs([]);
        setDocsError(`TOPIC ${activeTopicId} の文献データが未作成または読み込み不可です`);
        console.error('文献リストの読み込み失敗:', error);
      } finally {
        setDocsLoading(false);
      }
    };

    fetchTopicDocs();
  }, [activeTopicId]);

  const docsFiltered = useMemo(() => {
    const term = docsSearchTerm.trim().toLowerCase();
    const base = term
      ? topicDocs.filter((doc) => {
          const inventorText = Array.isArray(doc.inventors) ? doc.inventors.join(' ') : '';
          return (
            (doc.title || '').toLowerCase().includes(term) ||
            (doc.number || '').toLowerCase().includes(term) ||
            inventorText.toLowerCase().includes(term)
          );
        })
      : topicDocs;

    return base.slice(0, MAX_VISIBLE_DOCS);
  }, [topicDocs, docsSearchTerm]);

  const docsTopRanked = useMemo(
    () => docsFiltered.slice(0, MAX_SUBPANEL_RANK),
    [docsFiltered]
  );

  const docsForDisplay = useMemo(() => {
    const rangeToIndices = {
      '1-5': [0, 4],
      '6-10': [5, 9],
      '11-15': [10, 14],
      '16-20': [15, 19],
    };

    if (visibleRankRanges.length === 0) {
      return [];
    }

    const selectedIndices = new Set();
    visibleRankRanges.forEach((rangeKey) => {
      const range = rangeToIndices[rangeKey];
      if (!range) {
        return;
      }
      for (let i = range[0]; i <= range[1]; i += 1) {
        selectedIndices.add(i);
      }
    });

    return docsTopRanked
      .map((doc, idx) => ({ doc, rank: idx + 1 }))
      .filter((item) => selectedIndices.has(item.rank - 1));
  }, [docsTopRanked, visibleRankRanges]);

  const toggleVisibleRange = (rangeKey) => {
    setVisibleRankRanges((prev) =>
      prev.includes(rangeKey) ? prev.filter((item) => item !== rangeKey) : [...prev, rangeKey]
    );
  };

  const sanitizeFileName = (name) => {
    const normalized = String(name || '').trim();
    return normalized
      .replace(/[\\/:*?"<>|]/g, '_')
      .replace(/\s+/g, ' ')
      .slice(0, 120) || 'TOPIC';
  };

  const handleDownloadTopicDocs = async () => {
    if (!activeTopicId || topicDocs.length === 0) {
      return;
    }

    setIsDownloadingDocs(true);
    setDownloadError('');

    try {
      const basePath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${activeTopicId}/span=3`;
      const [companyRes, occupyRes] = await Promise.all([
        fetch(`${basePath}/setting/company.txt`, { cache: 'force-cache' }),
        fetch(`${basePath}/occupy/occupy_topic_5.json`, { cache: 'force-cache' }),
      ]);

      if (!companyRes.ok || !occupyRes.ok) {
        throw new Error(`HTTP ${!companyRes.ok ? companyRes.status : occupyRes.status}`);
      }

      const [companyText, occupySparse] = await Promise.all([companyRes.text(), occupyRes.json()]);
      const companyNames = companyText
        .split('\n')
        .map((line) => line.trim())
        .filter((line) => line !== '');

      const docsByCompanyRow = new Map();
      const companiesByDocCol = new Map();
      if (Array.isArray(occupySparse)) {
        occupySparse.forEach((entry) => {
          const row = Number(entry?.row);
          const col = Number(entry?.col);
          const value = Number(entry?.value);
          if (
            Number.isNaN(row) ||
            Number.isNaN(col) ||
            Number.isNaN(value) ||
            value <= 0 ||
            col < 0 ||
            col >= topicDocs.length
          ) {
            return;
          }
          if (!docsByCompanyRow.has(row)) {
            docsByCompanyRow.set(row, []);
          }
          docsByCompanyRow.get(row).push({ col, value });

          if (!companiesByDocCol.has(col)) {
            companiesByDocCol.set(col, []);
          }
          companiesByDocCol.get(col).push({ row, value });
        });
      }

      const rows = [];
      [...docsByCompanyRow.keys()]
        .sort((a, b) => a - b)
        .forEach((rowIndex) => {
          const companyName = companyNames[rowIndex] || `row_${rowIndex}`;
          const docs = docsByCompanyRow.get(rowIndex) || [];
          docs
            .sort((a, b) => a.col - b.col)
            .forEach(({ col, value }) => {
              const doc = topicDocs[col];
              if (!doc) {
                return;
              }
              rows.push({
                会社名: companyName,
                文献順位: col + 1,
                文献番号: doc.number || '',
                タイトル: doc.title || '',
                発明者: Array.isArray(doc.inventors) ? doc.inventors.join(' / ') : '',
                関連度: Number(value.toFixed(8)),
              });
            });
        });

      const workbook = XLSX.utils.book_new();

      // TOPIC内の文献を全件出力（会社対応がなくても全件ダウンロード可能にする）
      const allDocRows = topicDocs.map((doc, index) => {
        const relationEntries = (companiesByDocCol.get(index) || [])
          .slice()
          .sort((a, b) => b.value - a.value);
        const relatedCompanies = relationEntries.map((entry) => companyNames[entry.row] || `row_${entry.row}`);
        return {
          文献順位: index + 1,
          文献番号: doc.number || '',
          タイトル: doc.title || '',
          発明者: Array.isArray(doc.inventors) ? doc.inventors.join(' / ') : '',
          関連企業数: relatedCompanies.length,
          関連企業: relatedCompanies.join(' / '),
        };
      });
      const allDocSheet = XLSX.utils.json_to_sheet(allDocRows);
      XLSX.utils.book_append_sheet(workbook, allDocSheet, '全件文献');

      // 会社別の紐づき詳細（従来の一覧）
      const companyDocSheet = XLSX.utils.json_to_sheet(rows);
      XLSX.utils.book_append_sheet(workbook, companyDocSheet, '会社別文献一覧');

      const summarySheet = XLSX.utils.json_to_sheet(
        [...docsByCompanyRow.keys()]
          .sort((a, b) => a - b)
          .map((rowIndex) => ({
            会社名: companyNames[rowIndex] || `row_${rowIndex}`,
            文献件数: (docsByCompanyRow.get(rowIndex) || []).length,
          }))
      );
      XLSX.utils.book_append_sheet(workbook, summarySheet, '会社別件数');

      const topicLabel = getTopicLabel(activeTopicId, topicLabelMap);
      const fileName = `${sanitizeFileName(topicLabel)}_文献リスト.xlsx`;
      XLSX.writeFile(workbook, fileName);
    } catch (error) {
      console.error('文献リストXLSXの作成失敗:', error);
      setDownloadError('文献リストのXLSX作成に失敗しました');
    } finally {
      setIsDownloadingDocs(false);
    }
  };

  return (
    <Container fluid className="bg-light py-1" style={{ height: '100vh', overflow: 'hidden' }}>
      <div style={{ display: 'flex', gap: '8px', height: '100%' }}>
        <div style={{ width: `calc(100% - ${patentPanelWidth}px)`, minWidth: 0 }}>
          <div className="bg-light py-1" style={{ height: '100%', display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ height: '44vh', minHeight: 0 }}>
              {visualType === 'one-topic' ? (
                <PlotPersonaTopic
                  update={plot}
                  visualType={visualType}
                  topic={topic}
                  company={company}
                  topicLabelMap={topicLabelMap}
                  onRendered={resetApply}
                  onClickData={handlePersonaClick}
                  layout={{
                    title: 'ペルソナの可視化',
                    width: '100%',
                    height: '100%',
                  }}
                  config={{ responsive: true }}
                  style={{ width: '100%', height: '100%' }}
                  className="bg-light"
                />
              ) : visualType === 'one-comp' ? (
                <PlotPersonaComp
                  update={plot}
                  visualType={visualType}
                  topic={topic}
                  company={company}
                  topicLabelMap={topicLabelMap}
                  onRendered={resetApply}
                  layout={{
                    title: 'ペルソナの可視化',
                    width: '100%',
                    height: '100%',
                  }}
                  config={{ responsive: true }}
                  style={{ width: '100%', height: '100%' }}
                  className="bg-light"
                />
              ) : (
                <div>該当する表示がありません</div>
              )}
            </div>

            <Row className="g-2 mt-0 flex-grow-1" style={{ minHeight: 0 }}>
              <Col md={6} style={{ display: 'flex', minHeight: 0 }}>
                <Card className="w-100" style={{ height: '100%' }}>
                  <Card.Body className="p-2">
                    {visualType === 'one-topic' ? (
                      <PlotPieA
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        topicLabelMap={topicLabelMap}
                        onRendered={resetApply}
                        layout={{
                          title: '注目企業の業界に対する占有率',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : visualType === 'one-comp' ? (
                      <PlotPieB
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        topicLabelMap={topicLabelMap}
                        onRendered={resetApply}
                        onClickData={handlePieChartClick}
                        layout={{
                          title: '注目企業の業界に対する占有率',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : (
                      <div>該当する表示がありません</div>
                    )}
                  </Card.Body>
                </Card>
              </Col>
              <Col md={6} style={{ display: 'flex', minHeight: 0 }}>
                <Card className="w-100" style={{ height: '100%' }}>
                  <Card.Body className="p-2">
                    {visualType === 'one-topic' ? (
                      <PlotBarChartA
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        onRendered={resetApply}
                        data={[]}
                        layout={{
                          title: 'Fタームの分布',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : (
                      <PlotBarChartB
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        clickdata={clickData}
                        onRendered={resetApply}
                        data={[]}
                        layout={{
                          title: 'Fタームの分布',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    )}
                  </Card.Body>
                </Card>
              </Col>
            </Row>
          </div>
        </div>

        <div style={{ width: `${patentPanelWidth}px`, minWidth: `${patentPanelWidth}px`, maxWidth: '40vw' }}>
          <Card style={{ height: '100%' }} className="border-info-subtle">
            <Card.Body className="py-2 px-2 d-flex flex-column">
              <div style={{ position: 'sticky', top: 0, zIndex: 2, backgroundColor: 'white' }}>
                <div className="d-flex justify-content-between align-items-center mb-1">
                  <div className="text-muted" style={{ fontSize: '0.72rem' }}>TOPIC別 文献</div>
                  <Badge bg="secondary">{topicDocs.length}</Badge>
                </div>
                <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>TOPIC {activeTopicId || '-'}</div>

                <InputGroup size="sm" className="mb-1">
                  <Form.Control
                    placeholder="文献を検索"
                    value={docsSearchTerm}
                    onChange={(e) => setDocsSearchTerm(e.target.value)}
                    style={{ fontSize: '0.78rem', padding: '0.2rem 0.45rem' }}
                  />
                </InputGroup>

                <div className="d-flex justify-content-end mb-1">
                  <button
                    type="button"
                    className="btn btn-outline-success btn-sm me-2"
                    disabled={docsLoading || !!docsError || topicDocs.length === 0 || isDownloadingDocs}
                    onClick={handleDownloadTopicDocs}
                  >
                    {isDownloadingDocs ? '出力中...' : 'XLSXダウンロード'}
                  </button>
                  <button
                    type="button"
                    className="btn btn-outline-secondary btn-sm"
                    onClick={() => setIsRangeSettingOpen((prev) => !prev)}
                  >
                    設定
                  </button>
                </div>
              </div>

              {isRangeSettingOpen && (
                <div className="border rounded p-2 mb-2 bg-light">
                  <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>表示範囲（上位20位から選択）</div>
                  <div className="d-flex flex-wrap gap-2">
                    {['1-5', '6-10', '11-15', '16-20'].map((rangeKey) => (
                      <Form.Check
                        key={rangeKey}
                        type="checkbox"
                        id={`rank-range-${rangeKey}`}
                        label={`${rangeKey}位`}
                        checked={visibleRankRanges.includes(rangeKey)}
                        onChange={() => toggleVisibleRange(rangeKey)}
                        className="small"
                      />
                    ))}
                  </div>
                  <div className="mt-2 d-flex gap-2">
                    <button
                      type="button"
                      className="btn btn-outline-primary btn-sm"
                      onClick={() => setVisibleRankRanges(DEFAULT_VISIBLE_RANGES)}
                    >
                      デフォルト
                    </button>
                    <button
                      type="button"
                      className="btn btn-outline-secondary btn-sm"
                      onClick={() => setVisibleRankRanges(['1-5', '6-10', '11-15', '16-20'])}
                    >
                      1-20を全表示
                    </button>
                  </div>
                </div>
              )}

              {docsLoading && (
                <div className="text-muted" style={{ fontSize: '0.72rem' }}>
                  <Spinner size="sm" animation="border" className="me-2" />
                  読み込み中...
                </div>
              )}

              {!docsLoading && docsError && (
                <Alert variant="warning" className="mb-0 py-1 px-2" style={{ fontSize: '0.72rem' }}>
                  {docsError}
                </Alert>
              )}

              {!docsLoading && !docsError && downloadError && (
                <Alert variant="warning" className="mb-2 py-1 px-2" style={{ fontSize: '0.72rem' }}>
                  {downloadError}
                </Alert>
              )}

              {!docsLoading && !docsError && (
                <>
                  <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>
                    表示: {docsForDisplay.length} 件（検索結果上位20位から）
                  </div>
                  <ListGroup style={{ overflowY: 'auto', flex: 1, minHeight: 0 }}>
                    {docsForDisplay.map(({ doc, rank }) => (
                      <ListGroup.Item key={`${doc.number || 'doc'}-${rank}`} className="py-1 px-2">
                        <div className="fw-bold" style={{ fontSize: '0.76rem' }}>{rank}位: {doc.number}</div>
                        <div style={{ fontSize: '0.72rem' }}>{doc.title || '(タイトルなし)'}</div>
                      </ListGroup.Item>
                    ))}
                    {docsForDisplay.length === 0 && (
                      <ListGroup.Item className="text-muted" style={{ fontSize: '0.72rem' }}>
                        該当する文献はありません（設定の表示範囲もご確認ください）
                      </ListGroup.Item>
                    )}
                  </ListGroup>
                </>
              )}
            </Card.Body>
          </Card>
        </div>
      </div>

      {visualType === 'one-topic' && clickCompanyData && (
        <Row>
          <Col>
            <ProposedVisualize
              topic={topic}
              clickData={clickCompanyData}
              layout={{
                title: '任意の位置へ移動するための提案',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          </Col>
        </Row>
      )}
    </Container>
  );
};

export default Content;

